<?php
require_once __DIR__ . '/includes/auth.php'; require_login();
$id=(int)($_GET['id']??$_POST['id']??0);$userId=(int)$_SESSION['user_id'];$statement=$pdo->prepare('SELECT * FROM transactions WHERE id=:id AND user_id=:user_id');$statement->execute(['id'=>$id,'user_id'=>$userId]);$transaction=$statement->fetch();if(!$transaction){flash('error','Transaction not found.');redirect('transactions.php');}$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();[$errors,$data]=validate_transaction($_POST);if(!$errors){$update=$pdo->prepare('UPDATE transactions SET type=:type,amount=:amount,transaction_date=:transaction_date,note=:note WHERE id=:id AND user_id=:user_id');$update->execute(['type'=>$data['type'],'amount'=>$data['amount'],'transaction_date'=>$data['transaction_date'],'note'=>$data['note']?:null,'id'=>$id,'user_id'=>$userId]);flash('success','Transaction updated successfully.');redirect('transactions.php');}$transaction=array_merge($transaction,$data);}
$pageTitle='Edit transaction';require __DIR__.'/includes/header.php';
?><div class="page-title"><div><span class="eyebrow">TRANSACTION DETAIL</span><h1>Edit transaction</h1></div><a href="transactions.php" class="btn btn-outline-secondary">Back</a></div><section class="panel narrow-panel"><p class="muted">Update the details below. Only you can edit this transaction.</p><?php foreach($errors as $error): ?><div class="alert alert-danger py-2"><?=e($error)?></div><?php endforeach; ?><form method="post"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$id?>"><div class="row"><div class="col-md-6 mb-3"><label>Type</label><select class="form-select" name="type"><option <?= $transaction['type']==='Income'?'selected':'' ?>>Income</option><option <?= $transaction['type']==='Expense'?'selected':'' ?>>Expense</option></select></div><div class="col-md-6 mb-3"><label>Amount</label><input class="form-control" type="number" step="0.01" min="0.01" name="amount" value="<?=e((string)$transaction['amount'])?>" required></div></div><div class="row"><div class="col-md-6 mb-3"><label>Date</label><input class="form-control" type="date" name="transaction_date" value="<?=e($transaction['transaction_date'])?>" required></div><div class="col-md-6 mb-3"><label>Note</label><input class="form-control" name="note" value="<?=e($transaction['note']??'')?>" maxlength="255"></div></div><button class="btn btn-primary">Save changes</button></form></section><?php require __DIR__.'/includes/footer.php'; ?>
